CREATE TABLE blackfist_tv_seasons (id TEXT PRIMARY KEY NOT NULL, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, season_number INTEGER NOT NULL, title TEXT NOT NULL, synopsis TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL); CREATE UNIQUE INDEX blackfist_tv_seasons_project_number ON blackfist_tv_seasons(project_id,season_number); ALTER TABLE episodes ADD COLUMN blackfist_season_id TEXT REFERENCES blackfist_tv_seasons(id);